INF = 10 ** 9
def bf(E):
    d = [INF] * N
    d[0] = 0
    passes = 0
    while True:
        ch = False
        for a, b, w in E:
            if d[a] < INF and d[a] + w < d[b]:
                d[b] = d[a] + w
                ch = True
        if not ch:
